begin;

-- Curated master foods, generated from Eli's own portion table.
-- Stored per 100 g, scaled from his per-portion figures so one serving returns
-- his calories exactly. Calories are his and are never altered. Where a macro
-- cell was blank or could not hold against the calorie figure, the single
-- inconsistent field was recomputed so every row balances 4p + 4c + 9f.
-- The id prefix carries the group - master-p protein, master-c carbohydrate,
-- master-f fat - so the picker no longer depends on a hardcoded numeric list.
-- Rollback: supabase/seeds/curated-master-foods-rollback.sql

on conflict (id) do update set
  name = excluded.name, category = excluded.category, calories = excluded.calories,
  protein = excluded.protein, carbs = excluded.carbs, fat = excluded.fat,
  package_unit = excluded.package_unit, unit_weight_grams = excluded.unit_weight_grams,
  serving_label = excluded.serving_label, notes = excluded.notes, updated_at = now();

notify pgrst, 'reload schema';
commit;
